function sdkSummarizeMeasuredRun(row) {
    if (!row) return null;
    return {
        tokensPerSecond: sdkRound(row.observedTokS, 2),
        origin: row.isLab ? 'lab' : 'community',
        stack: row.isLab ? row.stack : 'stock',
        model: row.model,
        hardware: row.hardware,
        deviceCount: row.deviceCount || 1,
