class FakeElement {
  constructor(id = '', tagName = 'div') {
    this.id = id;
    this.tagName = tagName.toUpperCase();
    this.value = '';
    this.innerHTML = '';
    this.textContent = '';
    this.children = [];
    this.style = {};
    this.attributes = {};
    this.listeners = new Map();
    this.classList = new FakeClassList();
    this.dataset = {};
    this.checked = false;
    this.disabled = false;
    this.selected = false;
    this.width = 1200;
    this.height = 300;
    this.nextElementSibling = null;
  }

  appendChild(child) {
    this.children.push(child);
    child.parentElement = this;
    if (this.tagName === 'SELECT' && child.selected) {
      this.value = child.value;
    }
    return child;
  }

  addEventListener(type, handler) {
    if (!this.listeners.has(type)) {
      this.listeners.set(type, []);
    }
    this.listeners.get(type).push(handler);
  }

  dispatchEvent(type) {
    for (const handler of this.listeners.get(type) || []) {
      handler({ target: this });
    }
  }

  setAttribute(name, value) {
    this.attributes[name] = value;
  }

  removeAttribute(name) {
    delete this.attributes[name];
  }

  getContext() {
    return new FakeCanvasContext();
  }

  getBoundingClientRect() {
    return { width: 1200, height: 300 };
  }

  querySelector(selector) {
    if (this.id === 'systemAnalysis' && selector === '.rate-value') {
      const match = this.innerHTML.match(/<div class="rate-value">([\s\S]*?)<\/div>/);
      if (match) return { textContent: match[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim() };
    }
    if (this.id === 'systemAnalysis' && selector === '.ceiling-ladder .ladder-row[data-tier="is-engine"] .ladder-value strong') {
      const match = this.innerHTML.match(/<div class="ladder-row" data-tier="is-engine">[\s\S]*?<span class="ladder-value"><strong>([^<]+)<\/strong>/);
      if (match) return { textContent: match[1] };
    }
    return null;
  }

  querySelectorAll() {
    return [];
  }
}

function inferTagName(id) {
  if (['modelPreset', 'quantizationType', 'architectureType', 'routingType', 'attentionMechanism', 'dtype', 'parallelismStrategy', 'optimizationMode', 'runtimeFramework', 'batchSize', 'scenarioPreset', 'modelFilter', 'hardwareFilter', 'quantizationFilter'].includes(id)) {
    return 'select';
  }
  if (['utilizationChart', 'topologyCanvas'].includes(id)) {
    return 'canvas';
  }
  if (id === 'llmTable') {
    return 'table';
  }
  if (id === '__llmTableTbody') {
    return 'tbody';
  }
  if (id === 'loadDevicesBtn') {
    return 'button';
  }
  return 'input';
}

function createDocument(defaultValues) {
  const elements = new Map();
  const domReadyHandlers = [];

  const getElementById = (id) => {
    if (!elements.has(id)) {
      const element = new FakeElement(id, inferTagName(id));
      if (id in defaultValues) {
        element.value = String(defaultValues[id]);
      }
      elements.set(id, element);
    }
    return elements.get(id);
  };

  const document = {
    getElementById,
    createElement(tagName) {
      return new FakeElement('', tagName);
    },
    querySelector(selector) {
      if (selector === '#llmTable tbody') {
        return getElementById('__llmTableTbody');
      }
      return null;
    },
    querySelectorAll(selector) {
      if (selector === 'th[data-sort]' || selector === 'th') {
        return [];
      }
      if (selector === '#modelConfigContent input, #modelConfigContent select') {
        return [...elements.values()].filter(element => element.tagName === 'INPUT' || element.tagName === 'SELECT');
      }
      return [];
    },
    addEventListener(type, handler) {
      if (type === 'DOMContentLoaded') {
        domReadyHandlers.push(handler);
      }
    }
  };

  const requiredIds = [
    'modelPreset', 'quantizationType', 'totalParamsB', 'batchSize', 'promptTokens', 'outputTokens', 'seqLength', 'hiddenSize', 'numLayers',
    'numHeads', 'numKVHeads', 'intermediateSize', 'architectureType', 'activeParamsB', 'numExperts',
    'activeExperts', 'routingType', 'attentionMechanism', 'dtype', 'parallelismStrategy', 'optimizationMode',
    'kvCacheCompression', 'runtimeFramework', 'hoursPerDay', 'costPerKwh', 'systemAnalysis', 'alerts', 'utilizationChart',
    'devices', 'llmTable', '__llmTableTbody', 'modelFilter', 'hardwareFilter', 'quantizationFilter',
    'modelSummary', 'topologyCanvas', 'topologyContainer', 'executionMap', 'executionStrategyControls', 'loadDevicesBtn', 'scenarioPreset'
  ];

  requiredIds.forEach(getElementById);

  return { document, elements, domReadyHandlers };
}

